#!/usr/bin/env python3
# Generated by Claudian.
"""Honest evaluation on genuinely unseen phrasings.

The validation split in `train_intent_model.py` is drawn from the same
templates as the training data, so a "play {song}" val example is trivially
close to a "play {other song}" training example.  That inflates the reported
number.

Every utterance below was written by hand for this file and appears nowhere
in `intent_dataset.py` or `intent_augment.py`.  Different verbs, different
sentence shapes, contractions, and the clipped phrasing people actually use
when speaking.  This is the number to trust.

    python3 training/holdout_eval.py
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent))

# (utterance, expected_skill)
HOLDOUT: list[tuple[str, str]] = [
    # time_date
    ("got a clock on you", "time_date"),
    ("remind me what day this is", "time_date"),
    ("is it late", "time_date"),
    # open_app
    ("bring up the browser", "open_app"),
    ("i need excel open", "open_app"),
    ("boot up sublime text", "open_app"),
    # close_app
    ("get rid of the spotify window", "close_app"),
    ("shut safari please", "close_app"),
    # open_website
    ("load up my email in the browser", "open_website"),
    ("send me to twitch", "open_website"),
    # volume
    ("crank it", "volume"),
    ("bring the sound down a bit", "volume"),
    ("set the audio level to sixty", "volume"),
    # brightness
    ("screen is way too bright", "brightness"),
    ("crank the display brightness", "brightness"),
    # mute
    ("kill the audio", "mute"),
    ("i need silence right now", "mute"),
    # battery
    ("am i running out of power", "battery"),
    ("how many percent left on the battery", "battery"),
    # wifi
    ("tell me which router im on", "wifi"),
    ("what wireless network is this", "wifi"),
    # screenshot
    ("grab whats displayed right now", "screenshot"),
    ("snap a picture of my display", "screenshot"),
    # lock_screen
    ("i'm stepping away lock it", "lock_screen"),
    # empty_trash
    ("get rid of everything in the recycle bin", "empty_trash"),
    # music
    ("throw on some music", "music"),
    ("i wanna listen to coldplay", "music"),
    ("hit pause on the track", "music"),
    # search_local
    ("dig up that budget spreadsheet on my drive", "search_local"),
    ("where on this mac did i put the contract", "search_local"),
    # web_search
    ("look on the internet for a good mechanic", "web_search"),
    ("run a google search about tax deadlines", "web_search"),
    # news_headlines
    ("catch me up on world events", "news_headlines"),
    ("anything happening in tech today", "news_headlines"),
    # define_word
    ("give me the dictionary meaning of tenacious", "define_word"),
    ("what's the word petrichor mean", "define_word"),
    # wikipedia_lookup
    ("give me background on winston churchill", "wikipedia_lookup"),
    ("i want to read about the amazon rainforest", "wikipedia_lookup"),
    ("fill me in on who charles babbage was", "wikipedia_lookup"),
    # coding_assistant
    ("my python script keeps throwing an index error", "coding_assistant"),
    ("show me how to merge two dictionaries", "coding_assistant"),
    ("what's the point of a virtual environment", "coding_assistant"),
    ("walk me through setting up ci in github actions", "coding_assistant"),
    # system_stats
    ("is something eating all my ram", "system_stats"),
    ("give me a readout on the processor", "system_stats"),
    # jokes
    ("lighten the mood a bit", "jokes"),
    ("crack me up", "jokes"),
    # remember
    ("jot down that the spare key is under the mat", "remember"),
    ("hang on to this my badge number is 8842", "remember"),
    # recall
    ("what was that thing i told you about the spare key", "recall"),
    ("pull up what i saved earlier", "recall"),
    # whatsapp_send
    ("shoot priya a whatsapp saying im running late", "whatsapp_send"),
    # shutdown_jarvis
    ("alright thats it for now", "shutdown_jarvis"),
    ("you can rest now", "shutdown_jarvis"),
    # shutdown_system / restart_system
    ("power the whole machine down", "shutdown_system"),
    ("give the mac a reboot", "restart_system"),
    # conversation
    ("do you ever wonder about anything", "conversation"),
    ("i'm second guessing myself today", "conversation"),
    ("what's your take on all this", "conversation"),
    ("been a long week honestly", "conversation"),
    ("appreciate you sticking with me", "conversation"),
]


def main() -> int:
    from ai.intent_classifier_local import get_local_classifier

    clf = get_local_classifier()
    if not clf.available:
        print("Model not trained yet. Run:")
        print("  python3 training/train_intent_model.py --epochs 100")
        return 1

    gate = clf.threshold
    print("=" * 72)
    print("HOLDOUT EVALUATION — unseen phrasings".center(72))
    print("=" * 72)
    print(f"  examples: {len(HOLDOUT)}   confidence gate: {gate}")
    print()

    correct = 0
    gated_correct = 0
    gated_total = 0
    misses: list[str] = []

    for text, want in HOLDOUT:
        skill, conf = clf.predict(text)
        hit = skill == want
        correct += hit
        if conf >= gate:
            gated_total += 1
            gated_correct += hit
        if not hit:
            misses.append(f"    {text!r:52} {want} -> {skill} ({conf:.2f})")

    n = len(HOLDOUT)
    print(f"  Raw accuracy (always answer locally) : {correct}/{n} = {correct / n:.1%}")
    if gated_total:
        print(f"  Above gate  : {gated_total}/{n} = {gated_total / n:.1%} coverage, "
              f"{gated_correct / gated_total:.1%} accuracy")
        print(f"  Below gate  : {n - gated_total} utterances defer to the LLM")
    print()

    if misses:
        print("  Misclassified:")
        for m in misses:
            print(m)
    else:
        print("  No misclassifications.")
    print()
    print("=" * 72)
    return 0


if __name__ == "__main__":
    sys.exit(main())
